'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var E = require( '@stdlib/constants/float64/e' );


// VARIABLES //

var VARIANCE = E * ( E - 1.0 );


// MAIN //

/**
* Returns the variance for a gilbrat distribution with scale parameter `sigma`.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} variance
*
* @example
* var y = variance( 1.0 );
* // returns ~4.671
*
* @example
* var y = variance( NaN );
* // returns NaN
*
* @example
* var y = variance( 0.0 );
* // returns NaN
*/
function variance( sigma ) {
	if ( isnan( sigma ) || sigma <= 0.0 ) {
		return NaN;
	}
	return VARIANCE;
}


// EXPORTS //

module.exports = variance;
